import{_ as l,a0 as p,w as o,s as d,I as s,x as e,a1 as n,A as a,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何在 Linux 中從 PDF 創建視頻 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中從 PDF 創建視頻 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 中從 PDF 創建視頻 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中從 PDF 創建視頻 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20171004 How To Create A Video From PDF Files In Linux","title":"如何在 Linux 中從 PDF 創建視頻","tag":"201801","desc":""},"relativePath":"201801/20171004 How To Create A Video From PDF Files In Linux.md","filePath":"[post].md"}'),g={name:"201801/20171004 How To Create A Video From PDF Files In Linux.md"};function u(h,i,k,f,c,m){const t=p("Link");return o(),d("div",null,[i[17]||(i[17]=s("h1",{id:"如何在-linux-中從-pdf-創建視頻",tabindex:"-1"},[e("如何在 Linux 中從 PDF 創建視頻 "),s("a",{class:"header-anchor",href:"#如何在-linux-中從-pdf-創建視頻","aria-label":"Permalink to “如何在 Linux 中從 PDF 創建視頻”"},"​")],-1)),i[18]||(i[18]=s("p",null,[s("img",{src:"https://www.ostechnix.com/wp-content/uploads/2017/10/Video-1-720x340.jpg",alt:""})],-1)),s("p",null,[i[1]||(i[1]=e("我在我的平板電腦中收集了大量的 PDF 文件，其中主要是 Linux 教程。有時候我懶得在平板電腦上看。我認為如果我能夠從 PDF 創建視頻，並在大屏幕設備（如電視機或計算機）中觀看會更好。雖然我對 ",-1)),n(t,{href:"https://www.ostechnix.com/20-ffmpeg-commands-beginners/"},{default:a(()=>[...i[0]||(i[0]=[e("FFMpeg",-1)])]),_:1}),i[2]||(i[2]=e(" 有一些經驗，但我不知道如何使用它來創建視頻。經過一番 Google 搜索，我想出了一個很好的解決方案。對於那些想從一組 PDF 文件製作視頻文件的人，請繼續閲讀。這並不困難。",-1))]),i[19]||(i[19]=s("h3",{id:"在-linux-中從-pdf-創建視頻",tabindex:"-1"},[e("在 Linux 中從 PDF 創建視頻 "),s("a",{class:"header-anchor",href:"#在-linux-中從-pdf-創建視頻","aria-label":"Permalink to “在 Linux 中從 PDF 創建視頻”"},"​")],-1)),i[20]||(i[20]=s("p",null,"為此，你需要在系統中安裝 “FFMpeg” 和 “ImageMagick”。",-1)),i[21]||(i[21]=s("p",null,"要安裝 FFMpeg，請參考以下鏈接。",-1)),s("ul",null,[s("li",null,[n(t,{href:"https://www.ostechnix.com/install-ffmpeg-linux/"},{default:a(()=>[...i[3]||(i[3]=[e("在 Linux 上安裝 FFMpeg",-1)])]),_:1})])]),i[22]||(i[22]=r('<p>Imagemagick 可在大多數 Linux 發行版的官方倉庫中找到。</p><p>在 Arch Linux 以及 Antergos、Manjaro Linux 等衍生產品上，運行以下命令進行安裝。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S imagemagick</span></span></code></pre></div><p>Debian、Ubuntu、Linux Mint：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install imagemagick</span></span></code></pre></div><p>Fedora：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install imagemagick</span></span></code></pre></div><p>RHEL、CentOS、Scientific Linux：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo yum install imagemagick</span></span></code></pre></div><p>SUSE、 openSUSE：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo zypper install imagemagick</span></span></code></pre></div><p>在安裝 ffmpeg 和 imagemagick 之後，將你的 PDF 文件轉換成圖像格式，如 PNG 或 JPG，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>convert -density 400 input.pdf picture.png</span></span></code></pre></div><p>這裏，<code>-density 400</code> 指定輸出圖像的水平分辨率。</p><p>上面的命令會將指定 PDF 的所有頁面轉換為 PNG 格式。PDF 中的每個頁面都將被轉換成 PNG 文件，並保存在當前目錄中，文件名為： <code>picture-1.png</code>、 <code>picture-2.png</code> 等。根據選擇的 PDF 的頁數，這將需要一些時間。</p><p>將 PDF 中的所有頁面轉換為 PNG 格式後，運行以下命令以從 PNG 創建視頻文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ffmpeg -r 1/10 -i picture-%01d.png -c:v libx264 -r 30 -pix_fmt yuv420p video.mp4</span></span></code></pre></div><p>這裏：</p><ul><li><code>-r 1/10</code> ：每張圖像顯示 10 秒。</li><li><code>-i picture-%01d.png</code> ：讀取以 <code>picture-</code> 開頭，接着是一位數字（<code>％01d</code>），最後以 <code>.png</code> 結尾的所有圖片。如果圖片名稱帶有 2 位數字（也就是 <code>picture-10.png</code>、<code>picture11.png</code> 等），在上面的命令中使用（<code>％02d</code>）。</li><li><code>-c:v libx264</code>：輸出的視頻編碼器（即 h264）。</li><li><code>-r 30</code> ：輸出視頻的幀率</li><li><code>-pix_fmt yuv420p</code>：輸出的視頻分辨率</li><li><code>video.mp4</code>：以 .mp4 格式輸出視頻文件。</li></ul><p>好了，視頻文件完成了！你可以在任何支持 .mp4 格式的設備上播放它。接下來，我需要找到一種方法來為我的視頻插入一個很酷的音樂。我希望這也不難。</p><p>如果你想要更高的分辨率，你不必重新開始。只要將輸出的視頻文件轉換為你選擇的任何其他更高/更低的分辨率，比如説 720p，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ffmpeg -i video.mp4 -vf scale=-1:720 video_720p.mp4</span></span></code></pre></div><p>請注意，使用 ffmpeg 創建視頻需要一台配置好的 PC。在轉換視頻時，ffmpeg 會消耗大量系統資源。我建議在高端系統中這樣做。</p><p>就是這些了。希望你覺得這個有幫助。還會有更好的東西。敬請關注！</p><hr>',25)),s("p",null,[i[5]||(i[5]=e("via: ",-1)),n(t,{href:"https://www.ostechnix.com/create-video-pdf-files-linux/"},{default:a(()=>[...i[4]||(i[4]=[e("https://www.ostechnix.com/create-video-pdf-files-linux/",-1)])]),_:1})]),s("p",null,[i[9]||(i[9]=e("作者：",-1)),n(t,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...i[6]||(i[6]=[e("SK",-1)])]),_:1}),i[10]||(i[10]=e(" 譯者：",-1)),n(t,{href:"https://github.com/geekpi"},{default:a(()=>[...i[7]||(i[7]=[e("geekpi",-1)])]),_:1}),i[11]||(i[11]=e(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:a(()=>[...i[8]||(i[8]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[14]||(i[14]=e("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[12]||(i[12]=[e("LCTT",-1)])]),_:1}),i[15]||(i[15]=e(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:a(()=>[...i[13]||(i[13]=[e("Linux中國",-1)])]),_:1}),i[16]||(i[16]=e(" 榮譽推出",-1))])])}const F=l(g,[["render",u]]);export{C as __pageData,F as default};
